from math import gcd
from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 8)]
    grays = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]

    r0, r1 = min(r for r, c, v in marks), max(r for r, c, v in marks)
    c0, c1 = min(c for r, c, v in marks), max(c for r, c, v in marks)
    mh, mw = r1 - r0 + 1, c1 - c0 + 1

    # Reflect the colored pattern across the anti-diagonal.
    pattern = {}
    for r, c, v in marks:
        rr, cc = c - c0, mh - 1 - (r - r0)
        pattern[(rr, cc)] = v

    runs = []
    for row in grid:
        n = 0
        for x in row + [0]:
            if x == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
    for c in range(w):
        n = 0
        for r in range(h):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)
    unit = reduce(gcd, runs)

    top = min(r for r, c in grays)
    left = min(c for r, c in grays)
    out = [row[:] for row in grid]
    for r, c in grays:
        tr, tc = (r - top) // unit, (c - left) // unit
        if (tr, tc) in pattern:
            out[r][c] = pattern[(tr, tc)]
    return out
